 'use strict';
function setupTutorial(){run.tutorial={walk:false,jump:false,climb:false,normalAttack:false,hpPotion:false,mpPotion:false,startX:110};platforms=[{x:0,y:420,w:1200},{x:150,y:300,w:280}];ladders=[{x:210,top:300,bottom:420}];interactables=[];monsters=monsters.slice(0,3);monsters.forEach((m,i)=>{m.x=m.home=500+i*100;m.y=420;m.low=470+i*100;m.high=550+i*100;m.p=0});player.x=110;player.y=420;resetMotion();player.hp=Math.max(1,Math.floor(maxHP()*.7));player.mp=Math.floor(maxMP()*.7);renderTutorialHint()}
function tutorialMark(key){if(!run?.tutorial||run.finished||run.tutorial[key])return;run.tutorial[key]=true;renderTutorialHint()}
function updateTutorial(){const t=run?.tutorial;if(!t){const hint=document.getElementById('tutorialHint');if(hint)hint.hidden=true;return}if(Math.abs(player.x-t.startX)>=60)tutorialMark('walk');if(player.climbing)tutorialMark('climb');renderTutorialHint()}
function renderTutorialHint(){let hint=document.getElementById('tutorialHint');if(!hint){hint=document.createElement('div');hint.id='tutorialHint';hint.setAttribute('role','status');document.querySelector('.playfield').append(hint)}const t=run?.tutorial;hint.hidden=!t||run.finished;if(!t)return;hint.replaceChildren();const tasks=[['walk','← → เดิน'],['jump','Spacebar กระโดด'],['climb','↑ ↓ ปีนบันไดที่อยู่ด้านหน้า'],['normalAttack','C ตีปกติ · กดค้างเพื่อโจมตีต่อเนื่อง'],['hpPotion','Z ใช้ยาเพิ่ม HP'],['mpPotion','X ใช้ยาเพิ่ม MP']];for(const [id,text]of tasks){const row=document.createElement('div');row.textContent=(t[id]?'✓ ':'□ ')+text;row.classList.toggle('done',!!t[id]);hint.append(row)}{const done=document.createElement('strong');done.textContent='เดินเข้าวาร์ปด้านขวา · กด Spacebar เพื่อโต้ตอบและจบการฝึก';hint.append(done)}}
function drawTutorialSign(){}

function drawTutorialPortalPrompt(){const exit=interactables.find(t=>t.kind==='portal');if(!exit||Math.abs(player.x-exit.x)>100)return;ctx.font='12px Thai,Tahoma';ctx.textAlign='center';ctx.fillStyle='#173929';ctx.fillRect(exit.x-83,exit.y-132,166,27);ctx.fillStyle='#f3dc9e';ctx.fillText('Spacebar เพื่อโต้ตอบ',exit.x,exit.y-114)}
